import type { Metadata } from "next";
import routes from "@/content/routes.json";

export const siteUrl = "https://dsdinvest.com";
export const siteName = "DSD Invest";
export const siteTitle =
  "DSD Invest | Studenterdrevet investeringsorganisation";
export const siteDescription =
  "En dansk, studenterdrevet og forskningsbaseret investeringsorganisation, hvor fundamental analyse, probabilistiske prognoser og kvantitativ porteføljekonstruktion møder næste generation af investeringstalent.";

/** Link-preview image generated by `src/app/opengraph-image.tsx`. */
const previewImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "DSD Invest – Disciplineret kapital. Drevet af studerende.",
};

/** Shared link-preview fields; pages override the title. */
const openGraph = {
  siteName,
  locale: "da_DK",
  type: "website",
  description: siteDescription,
  images: [previewImage],
} satisfies Metadata["openGraph"];

export const rootMetadata: Metadata = {
  metadataBase: new URL(siteUrl),
  title: siteTitle,
  description: siteDescription,
  applicationName: siteName,
  openGraph: { ...openGraph, title: siteTitle, url: "/" },
  twitter: {
    card: "summary_large_image",
    title: siteTitle,
    description: siteDescription,
    images: [previewImage],
  },
};

export function pageMetadata(pathname: string): Metadata {
  const title =
    routes.find((route) => route.path === pathname)?.metadataTitle ?? siteTitle;
  return {
    title,
    openGraph: { ...openGraph, title, url: pathname },
    twitter: {
      card: "summary_large_image",
      title,
      description: siteDescription,
      images: [previewImage],
    },
  };
}
